INSERT INTO `financial_institution` VALUES (2, '中国建设银行', 2, '周刚静', '海南省\r\n海口市\r\n龙华区', NULL, '生物医药', '公司设有6个部门，包含行政人事部、销售部、实验部、项目管理部、产品部、生物信息部。共有员工32人，其中硕士以上学历18人，公司核心团队成员从事高通量测序领域8年以上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (3, '农业银行', 3, '褚丽泽', '海南省\r\n海口市\r\n秀英区', NULL, '现代物流', '贵州现代物流产业（集团）有限责任公司系按照贵州省委省政府打造“四梁八柱”工业体系的要求，以原贵州省物资集团有限责任公司和原贵州省商贸投资集团有限责任公司为基础组建设立，是省政府批准成立的唯一涉及农产品流通最多并明确有行业主管部门的省管国有大一型企业集团，于2018年9月28日正式挂牌，下辖11户全资子公司、5户控股公司和7户参股公司,注册资本50亿元。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (4, '海南现代服务集团有限公司', 4, '孔洋', '海南省\r\n海口市\r\n龙华区', NULL, '新型服务', '瓜子二手车，成立于2015年9月。瓜子二手车一直致力于通过创业重塑二手车行业。瓜子二手车有瓜子严选、全国购（及开放平台）和车速拍等业务体系，业务覆盖全国200多座主流城市。 2021年9月，瓜子二手车宣布正式切换为新电商模式，实现二手车非标品的线上售卖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (5, '海南文创投资有限公司', 5, '蒋红', '海南省\r\n三亚市\r\n', NULL, '文化教育', '李宁公司创立于1990年，三十多年我们不断探索和创新，以“用运动燃烧激情”为使命，致力于专业体育用品的创造，努力让运动改变生活，追求更高境界的突破。我们秉承\"消费者导向\"的核心价值观，致力于成为源自中国并被世界认可的国际一流具有时尚属性的专业运动品牌企业。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (6, '海南云数科技有限公司', 6, '孔平宇', '海南省\r\n海口市\r\n秀英区', NULL, '大数据', '华盛恒辉是一家专注于高端软件定制开发服务和高端建设的服务机构，致力于为企业提供全面、系统的开发制作方案。在开发、建设到运营推广领域拥有丰富经验，我们通过建立对目标客户和用户行为的分析，整合高质量设计和极其新技术，为您打造创意十足、有价值的企业品牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (7, '海南京航新材料股份有限公司', 7, '朱文强', '海南省\r\n海口市\r\n琼山区', NULL, '新材料', '公司业务范围覆盖装备制造、新能源、轨道交通、航空航天、电子信息、半导体、国防军工以及低碳环保等新兴产业等。公司一直以来以技术创新为第一核心竞争力，拥有多项领先、具有竞争力的胶粘剂新材料、电磁兼容设备、电源模块技术，其中多个系列的产品性能已经达到或已经超过国内、国际同类产品的水平，为客户提供系统化解决方案。公司未来将大力发展功能性高分子新材料，以胶粘剂为主，特种树脂为支撑，结合自身资源与优势向电子信息材料、高性能复合材料等方向纵深发展转型，完善军工领域的战略布局', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (8, '海南绿能新能源投资有限公司', 8, '曹艳', '海南省\r\n海口市\r\n龙华区', NULL, '新能源', '理想汽车是中国新能源汽车制造商，设计、研发、制造和销售豪华智能电动汽车，于2015年7月创立，通过产品创新及技术研发，为家庭用户提供安全及便捷的产品及服务。李想是中国著名的连续创业家，曾创办全球访问量最大的汽车网站汽车之家（NYSE:ATHM）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (9, '海南精机装备制造有限公司', 9, '张志', '海南省\r\n三亚市\r\n', NULL, '高端制备', '公司创建于2005年，是一家专业生产液压元件与液压系统的企业，凭借着过硬的研发制造团队，公司已形成了拥有多产品的自主知识产权的技术体系，核心技术涵盖高精密液压铸造技术，摩擦焊接技术，热处理技术等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
INSERT INTO `financial_institution` VALUES (10, '海南智飞航空科技有限公司', 10, '金平睿', '海南省\r\n海口市\r\n美兰区', NULL, '智能制造', 'DJI 大疆创新,致力于成为持续推动人类进步的科技公司。你可以了解DJI Mavic 3、DJI Air 2S、DJI FPV等航拍无人机,DJI Pocket 2等手持摄影产品,和Ronin、Inspire等专业影像设备。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/static/defaultImage/1.png', NULL, NULL, '/static/defaultImage/1.png', NULL);
