INSERT INTO `financial_product` VALUES (1, '小微企业短期信用贷', '2020-11-04 14:23:12', '面向注册满一年的小微企业，提供短期流动资金信用贷款支持，无需抵押担保，审批便捷，最快3个工作日放款。', '/static/defaultImage/1.png', '15.70%-45.35%', '100万及以下', '信用', '3个月及以下', '1.企业注册满一年且经营正常；2.企业及法定代表人信用记录良好；3.年营业额不低于50万元；4.提供近半年银行流水。', 10, 1, '政府担保贴息类', NULL);
INSERT INTO `financial_product` VALUES (2, '科技型企业中长期发展贷', '2020-12-08 14:36:12', '为高新技术企业提供中长期资金支持，由政府信保基金提供担保，降低企业融资门槛，助力科技研发和产能扩张。', '/static/defaultImage/1.png', '6.27%-17.89%', '200万及以下', '信保基金', '36个月以上', '1.持有有效期内的高新技术企业认定证书；2.企业连续经营满两年；3.无不良信用记录及未结诉讼；4.提供近两年的财务报表及纳税证明。', 11, 1, '政府担保贴息类', NULL);
INSERT INTO `financial_product` VALUES (3, '银行快捷经营贷', '2020-10-30 22:00:32', '银行自主推出的信用贷款产品，专为有稳定经营流水的小微企业设计，线上申请、快速审批、随借随还。', '/static/defaultImage/1.png', '5.19%-25.35%', '300万及以下', '信用', '12个月及以下', '1.企业成立满一年且纳税正常；2.纳税信用等级B级（含）以上；3.提供近一年增值税纳税申报表；4.法定代表人无不良征信记录。', 11, 1, '银行自主产品', NULL);
INSERT INTO `financial_product` VALUES (4, '成长型企业专项扶持贷', '2021-03-30 01:09:23', '针对快速成长的中型企业提供的专项扶持贷款，由政府信保基金提供担保，解决企业扩张期的资金需求。', '/static/defaultImage/1.png', '10.50%-20.50%', '500万及以下', '信保基金', '6个月及以下', '1.年营业收入增长率超过20%；2.获得信保基金推荐函；3.企业成立满两年；4.提供近两年审计报告及未来一年经营计划。', 10, 1, '政府担保贴息类', NULL);
INSERT INTO `financial_product` VALUES (5, '产业园入驻企业配套贷', '2021-05-22 08:09:23', '为省级以上科技产业园区入驻企业提供的配套融资服务，结合园区政策，为企业提供灵活多样的资金支持。', '/static/defaultImage/1.png', '15.70%-45.35%', '500万及以下', '信保基金', '36个月及以下', '1.入驻省级以上科技产业园且在园区内正常经营；2.经营满一年并按时缴纳租金；3.无重大违法违规记录；4.提供园区入驻协议及租金缴纳凭证。', 11, 1, '其他', NULL);
INSERT INTO `financial_product` VALUES (6, '大型企业经营周转贷', '2022-06-22 08:09:23', '满足大型企业短期经营周转需求的信用贷款产品，额度高、放款快，支持企业应对季节性资金需求。', '/static/defaultImage/1.png', '6.27%-17.89%', '1000万及以下', '信用', '12个月及以下', '1.年营业额不低于5000万元；2.企业信用评级AA级（含）以上；3.连续经营满三年；4.提供近三年审计报告及近期财务报表。', 11, 1, '其他', NULL);
INSERT INTO `financial_product` VALUES (7, '政府贴息创业贷', '2022-03-12 12:09:23', '面向初创企业的政府担保贴息贷款，享受财政贴息支持，显著降低企业融资成本，助力创业起步。', '/static/defaultImage/1.png', '5.19%-25.35%', '200万及以下', '信保基金', '12个月及以下', '1.成立三年内的初创企业；2.拥有自主知识产权或核心技术；3.创始人及团队具备相关行业经验；4.提供商业计划书及知识产权证书。', 11, 1, '政府担保贴息类', NULL);
INSERT INTO `financial_product` VALUES (8, '企业信用长期发展贷', '2020-11-04 14:23:12', '基于企业信用评估的中长期贷款，支持企业设备更新、技术改造和市场拓展，期限最长可达三年。', '/static/defaultImage/1.png', '10.50%-20.50%', '300万及以下', '信用', '36个月以上', '1.连续经营满三年且无不良记录；2.纳税信用等级A级；3.近一年纳税额不低于10万元；4.提供详细资金用途说明及还款计划。', 10, 1, '其他', NULL);
INSERT INTO `financial_product` VALUES (9, '重大项目政府贴息贷', '2022-08-25 08:09:23', '支持省级以上重大项目的专项政府贴息贷款，优先支持高新技术产业、绿色能源等重点领域。', '/static/defaultImage/1.png', '20.17%-32.65%', '1000万以上', '信用', '12个月及以下', '1.项目列入省级重大项目清单；2.项目可行性研究报告通过专家评审；3.企业具备项目实施资质；4.提供项目批复文件及资金使用计划。', 11, 1, '政府担保贴息类', NULL);
INSERT INTO `financial_product` VALUES (10, '小微企业信用快贷', '2021-07-12 17:09:23', '专为小微企业打造的快速信用贷款，线上提交申请、系统自动审批，无需抵押，最快当天放款。', '/static/defaultImage/1.png', '15.7%-45.35%', '200万及以下', '信用', '12个月及以下', '1.小微企业主或个体工商户；2.经营满六个月且有稳定流水；3.征信无当前逾期；4.提供营业执照及近三个月银行流水。', 11, 1, '其他', NULL);
INSERT INTO `financial_product` VALUES (11, '知识产权质押短期融资', '2022-07-15 09:46:48', '以专利、商标等知识产权为质押物的短期融资产品，盘活企业无形资产，解决临时性资金需求。', '/static/defaultImage/1.png', '4%以下', '501万-1000万', '质押', '6个月及以下', '1.拥有有效发明专利或注册商标权；2.质押物经评估价值不低于600万元；3.知识产权无权属纠纷；4.提供知识产权证书及评估报告。', 28, 0, NULL, NULL);
INSERT INTO `financial_product` VALUES (13, '不动产抵押经营周转贷', '2022-09-06 16:31:37', '以企业名下不动产为抵押的短期经营周转贷款，额度充足、利率合理，适合有固定资产的企业。', '/static/defaultImage/1.png', '6%以上', '201万-300万', '抵押', '6个月及以下', '1.拥有海南省内商业房产或工业用地；2.产权清晰无抵押或剩余价值充足；3.企业经营满一年；4.提供房产证/土地证及评估报告。', 35, 0, NULL, NULL);
INSERT INTO `financial_product` VALUES (14, '房产抵押小额快速贷', '2022-09-18 10:48:47', '以住宅或商铺为抵押的小额快速贷款，利率优惠，审批流程简便，满足企业短期资金需求。', '/static/defaultImage/1.png', '4%以下', '100万及以下', '抵押', '3个月及以下', '1.抵押物位于海口或三亚市区；2.房龄不超过20年；3.房产评估值不低于150万元；4.产权人同意抵押并提供相关证明。', 27, 0, NULL, NULL);
INSERT INTO `financial_product` VALUES (15, '设备抵押短期流动资金贷', '2022-09-29 10:10:16', '以生产设备为抵押的短期流动资金贷款，帮助企业盘活固定资产，解决原材料采购等资金周转问题。', '', '4%以下', '100万及以下', '抵押', '3个月及以下', '1.设备购置年限不超过五年；2.设备评估值不低于120万元；3.设备产权清晰无其他抵押；4.提供设备购置发票及评估报告。', 43, 0, NULL, NULL);
INSERT INTO `financial_product` VALUES (16, '车辆抵押应急周转贷', '2022-09-29 13:46:59', '以企业名下车辆为抵押的应急周转贷款，快速评估、快速放款，帮助企业应对突发性资金缺口。', '', '6%以上', '100万及以下', '抵押', '3个月及以下', '1.车辆登记在企业名下；2.车龄不超过八年；3.车辆评估值不低于30万元；4.提供车辆登记证、行驶证及评估报告。', 46, 0, NULL, NULL);
INSERT INTO `financing_need` VALUES (1, '充电桩基础设施建设项目', '2022-07-25 15:02:11.000000', '充电桩产品系列齐全：\n第一代充电桩产品有：交流充电桩、落地式直流充电桩，整机功率≤180KW；\n第二代充电桩产品有：交流充电桩、便携式直流充电桩、落地式直流充电桩，整机功率≤400KW。', '新能源及节能技术领域', '/static/defaultImage/1.png', '某电源股份有限公司（股票代码：300XXX）是一家专注于太阳能、风能、储能、氢能、电动汽车等新能源电源设备的研发、生产、销售和服务的国家重点高新技术企业。主要产品有光伏逆变器、风电变流器、储能系统、水面光伏系统、新能源汽车驱动系统、充电设备、可再生能源制氢系统、智慧能源运维服务等，并致力于提供全球一流的清洁能源全生命周期解决方案。', '融资2000万，出让20%股权，寻求银行贷款500万', '1001万及以上', '债务性融资', '其他', 16, 1, 1, 0, '吕娟', '18377406486', 'financing_need1@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (2, '海洋生物多组学科研服务产业化', '2022-03-25 15:05:44.000000', '细胞器多组学科研和医学服务产业化，突破细胞器分离纯化难题', '生物与新医药技术领域', '/static/defaultImage/1.png', '公司设有6个部门，包含行政人事部、销售部、实验部、项目管理部、产品部、生物信息部。共有员工32人，其中硕士以上学历18人，公司核心团队成员从事高通量测序领域8年以上。', '细胞器多组学科研和医学服务产业化项目融资300万，出让5%股权', '101万-200万', '出让股权', '其他', 18, 1, 2, 0, '陈静怡', '13520687639', 'financing_need2@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (3, '智慧园区数字孪生可视化平台', '2022-04-25 15:02:11.000000', '基于Thongjs-X数字孪生可视化平台打造的智慧园区运营管理系统，整合园区管理现有信息系统数据资源，通过数字孪生技术将真实的园区进行还原，采用从园区、到建筑、楼层和设备的层级三维可视化方式进行展现。系统可广泛应用于政府园区、商业园区和工业园区等场所，实现园区环境生态监控、能耗监控、运营管理、公众展示服务、数字招商展示等多种综合管理功能', '电子信息技术领域', '/static/defaultImage/1.png', '某州现代物流产业（集团）有限责任公司系按照某州省委省政府打造“五梁九柱”工业体系的要求，以原某州省物资集团有限责任公司和原某州省商贸投资集团有限责任公司为基础组建设立，是省政府批准成立的唯一涉及农产品流通最多并明确有行业主管部门的省管国有大一型企业集团，于20XX年X月2X日正式挂牌，下辖15户全资子公司、5户控股公司和7户参股公司,注册资本50亿元。', '将信息、运输、仓储、库存、装卸搬运以及包装等物流活动综合起来的一种新型的集成式管理，其任务是尽可能降低物流的总成本，为顾客提供最好的服务。', '100万及以下', '短期负债融资', '其他', 12, 3, 1, 1, '许丽辉', '18234036761', 'financing_need3@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (4, '旅游互动服务平台', '2022-05-25 15:02:11.000000', '互动服务 让顾客尝鲜服务的个性化就是要满足顾客的个性化需求,要求一 切从顾客的要求出发,对每一位顾客开展差异性服务。现代经济已经是体验经济, ', '高技术服务业领域', '/static/defaultImage/1.png', '某瓜二手车，成立于20XX年9月。某瓜二手车一直致力于通过创业重塑二手车行业。某瓜二手车有某瓜严选、全国购（及开放平台）和车速拍等业务体系，业务覆盖全国200多座主流城市。 2021年9月，某瓜二手车宣布正式切换为新电商模式，实现二手车非标品的线上售卖。', '新兴服务业是指伴随着信息技术的发展和知识经济的出现、伴随着社会分工的细化和消费结构的升级而新生的行业，或用现代化的新技术、新业态和新的服务方式改造提升传统服务业而产生的，向社会提供高附加值、满足社会高层次和多元化需求的服务业。', '其他金额', '债务性融资', '其他', 16, 5, 2, 1, '魏艳然', '13154981285', 'financing_need4@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (5, '在线教育平台', '2021-06-25 15:02:11.000000', '新西方网(www.XXX.XXX)是新西方教育科技集团推出的互动学习交流平台,新西方网的内容涵盖了英语学习规划、成长导航、新西方搜课、在线咨询、学习资讯、新西方学员服务等,更多精彩内容尽在新西方网。', '其他', '/static/defaultImage/1.png', '某宁公司创立于199X年，三十多年我们不断探索和创新，以“用运动燃烧激情”为使命，致力于专业体育用品的创造，努力让运动改变生活，追求更高境界的突破。我们秉承\"消费者导向\"的核心价值观，致力于成为源自某国并被世界认可的国际一流具有时尚属性的专业运动品牌企业。', '体育文化，广义是指人类在历史发展进程中，在体育方面创造的一切物质文明与精神文明的总和；狭义往往是指有关体育的精神文明或观念文化。而体育文化工作则是指体育宣传报道、体育赛事转播、体育报刊书籍、体育音乐电影等操作层面的活动。', '501万-1000万', '权益融资', '其他', 16, 1, 1, 1, '赵军', '13868047987', 'financing_need5@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (6, '旅游大数据分析平台', '2021-06-23 15:02:11.000000', '自助BI报表分析和制作可视化数据大屏的强大工具。基于某度Bcharts提供丰富的图表组件，开箱即用、零代码操作、无需SQL，5分钟即可完成数据可视化页面的搭建，降低开发成本的同时，提高业务对数据的使用效率，助力企业精准快速决策。', '电子信息技术领域', '/static/defaultImage/1.png', '百变某度是一家专注于高端软件定制开发服务和高端建设的服务机构，致力于为企业提供全面、系统的开发制作方案。在开发、建设到运营推广领域拥有丰富经验，我们通过建立对目标客户和用户行为的分析，整合高质量设计和极其新技术，为您打造创意十足、有价值的企业品牌。', '大数据(big data)，或称巨量资料，指的是所涉及的资料量规模巨大到无法透过主流软件工具，在合理时间内达到撷取、管理、处理、并整理成为帮助企业经营决策更积极目的的资讯。', '101万-200万', '债务性融资', '其他', 22, 2, 1, 1, '王静', '13629008854', 'financing_need6@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (7, '新型环保建材研发', '2021-07-25 15:02:11.000000', '富某特新材料科技发展股份有限公司始创于2000年,主要产品包括:真石漆,外墙外保温系统,仿石涂料,保温砂浆,环氧地坪漆,质感涂料,外墙涂料等,是某国十大涂料品牌,是集建筑涂料、保温、地坪的研发', '新材料技术领域', '/static/defaultImage/1.png', '公司业务范围覆盖装备制造、新能源、轨道交通、航空航天、电子信息、半导体、国防军工以及低碳环保等新兴产业等。公司一直以来以技术创新为第一核心竞争力，拥有多项领先、具有竞争力的胶粘剂新材料、电磁兼容设备、电源模块技术，其中多个系列的产品性能已经达到或已经超过国内、国际同类产品的水平，为客户提供系统化解决方案。公司未来将大力发展功能性高分子新材料，以胶粘剂为主，特种树脂为支撑，结合自身资源与优势向电子信息材料、高性能复合材料等方向纵深发展转型，完善军工领域的战略布局', '在选择投资者时，通常应考虑到地域、行业重点、发展阶段以及所需资金量等因素。其它一些因素也同等重要，例如投资者在融资中是否为主投方，已投资过的企业是否会与你的公司进行互补或竞争。', '501万-1000万', '权益融资', '其他', 16, 2, 2, 0, '褚娟勇', '15073945414', 'financing_need7@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (8, '新能源汽车充电网络', '2021-08-25 15:02:11.000000', '梦想汽车是某国新能源汽车制造商，设计、研发、制造和销售豪华智能电动汽车，于20XX年7月创立，通过产品创新及技术研发，为家庭用户提供安全及便捷的产品及服务。', '新能源及节能技术领域', '/static/defaultImage/1.png', '梦想汽车是某国新能源汽车制造商，设计、研发、制造和销售豪华智能电动汽车，于20XX年7月创立，通过产品创新及技术研发，为家庭用户提供安全及便捷的产品及服务。孟想是某国著名的连续创业家，曾创办全球访问量最大的汽车网站汽车之家。', '新能源( NE）：又称非常规能源。是指传统能源之外的各种能源形式。指刚开始开发利用或正在积极研究、有待推广的能源，如太阳能、地热能、风能、海洋能、生物质能和核聚变能等。', '100万及以下', '权益融资', '其他', 15, 1, 1, 0, '章军', '18561125602', 'financing_need8@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (9, '智能穿戴设备研发', '2022-01-25 15:02:11.000000', '华子智能手表是华为推出的首款智能手表产品，于2015年9月2日在IFA2015上正式发布。于2015年11月27号接受预约，2015年12月9日发售。2020年第一季度，华子智能手表出货量市场占比排名第二。', '先进制造与自动化领域', '/static/defaultImage/1.png', '公司创建于2005年，是一家专业生产液压元件与液压系统的企业，凭借着过硬的研发制造团队，公司已形成了拥有多产品的自主知识产权的技术体系，核心技术涵盖高精密液压铸造技术，摩擦焊接技术，热处理技术等。', '新能源( NE）：又称非常规能源。是指传统能源之外的各种能源形式。指刚开始开发利用或正在积极研究、有待推广的能源，如太阳能、地热能、风能、海洋能、生物质能和核聚变能等。', '501万-1000万', '债务性融资', '其他', 12, 3, 1, 1, '郑勇强', '13651275714', 'financing_need9@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (10, '跨海通道工程技术', '2022-02-25 15:02:11.000000', '这条由某国铁某院总院设计的，某国内地首条穿海地铁隧道，是某市级单位地铁2号线。它也是市级单位开通的第二条地铁线路，标志这地铁从单线到双线，真正进入了“换乘”时代。它全长41.6公里，设置了三十二个地下车站，而过海隧道则长达2784米，区间穿越了两条断裂带。', '航空航天技术领域', '/static/defaultImage/1.png', '某创新型公司,致力于成为持续推动人类进步的科技公司。你可以了解 Mavic 3、 Air 2S、 FPV等航拍无人机, Pocket 2等手持摄影产品,和Ronin、Inspire等专业影像设备。', '智能制造，源于人工智能的研究，一般认为智能是知识和智力的总和，前者是智能的基础，后者是指获取和运用知识求解的能力。', '1001万及以上', '短期负债融资', '其他', 15, 1, 1, 1, '谢娟', '13273402024', 'financing_need10@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (11, '三亚热带水果深加工产业园', '2022-09-29 10:40:32.000000', '建设以芒果、荔枝、火龙果等海南特色热带水果为主的深加工产业园，包括冷链仓储、果汁加工、果干制作、果蔬脆片等生产线，打造热带水果全产业链示范基地。', '食品加工', '/static/defaultImage/1.png', '团队由热带农业专家、食品加工工程师和市场营销人员组成，拥有15年热带水果种植与加工经验。', '计划融资3000万元，出让15%股权，用于建设标准化厂房和采购先进加工设备。', '1001万及以上', '出让股权', '天使轮', 44, 0, 2, 1, '蒋梅涛', '15159429553', 'financing_need11@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (12, '海口江东新区数据中心', '2022-09-29 10:40:40.000000', '在海口江东新区建设绿色低碳数据中心，为海南自由贸易港提供云计算、大数据存储、人工智能算力等数字基础设施服务，PUE值控制在1.3以下。', '电子信息技术领域', '/static/defaultImage/1.png', '核心团队来自国内头部互联网企业数据中心部门，拥有丰富的IDC建设和运营经验。', '计划融资8000万元，出让10%股权，用于数据中心土建和IT设备采购。', '1001万及以上', '出让股权', 'A轮', 44, 0, 1, 1, '曹艳辰', '18853029173', 'financing_need12@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (13, '文昌航天旅游综合体', '2022-09-29 10:41:12.000000', '依托文昌航天发射场，建设集航天科普教育、主题游乐、休闲度假、商业配套于一体的航天旅游综合体，打造海南国际旅游岛新名片。', '高技术服务业领域', '/static/defaultImage/1.png', '团队拥有旅游开发、航天科普、主题乐园运营等复合背景。', '计划融资1.5亿元，出让20%股权，寻求战略投资者共同开发。', '1001万及以上', '出让股权', 'Pre-A轮', 44, 0, 1, 1, '王红辉', '13653154400', 'financing_need13@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (14, '博鳌乐城医疗健康产业园', '2022-09-29 10:42:51.000000', '在博鳌乐城国际医疗旅游先行区建设医疗健康产业园，引进国际先进医疗技术、设备和药品，开展特许医疗、特许研究、特许经营等业务。', '生物与新医药技术领域', '/static/defaultImage/1.png', '核心团队由海归医学博士、医院管理专家和政策研究人员组成。', '计划融资5000万元，出让12%股权，用于园区基础设施建设和设备引进。', '1001万及以上', '出让股权', 'A轮', 44, 0, 1, 1, '沈刚然', '15114825554', 'financing_need14@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (15, '海南自贸港跨境电商物流园', '2022-09-29 12:13:47.000000', '建设海南自贸港跨境电商综合物流园，提供保税仓储、分拣配送、通关服务、供应链金融等一站式解决方案，助力海南成为跨境电商区域性枢纽。', '高技术服务业领域', '/static/defaultImage/1.png', '团队拥有跨境电商、国际物流、供应链管理等多领域经验。', '计划融资4000万元，出让18%股权，用于园区建设和信息系统开发。', '1001万及以上', '出让股权', '天使轮', 27, 0, 1, 1, '周秀', '13718234238', 'financing_need15@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (16, '三亚深海科技产业园区', '2022-09-29 12:13:56.000000', '在三亚建设深海科技产业园区，聚焦深海探测装备、海洋资源开发、深海生物制药等领域，打造国家深海科技南方基地。', '海洋工程装备', '/static/defaultImage/1.png', '团队由海洋工程专家、深海探测研究员和产业园区运营人才组成。', '计划融资6000万元，出让15%股权，用于园区建设和科研设备采购。', '1001万及以上', '出让股权', 'Pre-A轮', 27, 0, 1, 1, '沈霞', '15195458756', 'financing_need16@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (17, '海南环岛旅游公路驿站', '2022-09-29 12:14:09.000000', '围绕海南环岛旅游公路建设特色驿站网络，融合当地文化、美食、住宿、休闲等功能，打造海南全域旅游新亮点。', '高技术服务业领域', '/static/defaultImage/1.png', '团队拥有旅游规划、建筑设计、民宿运营等专业背景。', '计划融资2000万元，出让25%股权，用于首批驿站建设和品牌推广。', '501万-1000万', '出让股权', '天使轮', 27, 0, 1, 1, '姜军', '13262596645', 'financing_need17@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
INSERT INTO `financing_need` VALUES (18, '海口国家高新区生物医药基地', '2022-09-29 13:14:51.000000', '在海口国家高新区建设生物医药产业化基地，重点发展创新药物、高端医疗器械、再生医学等领域，打造海南生物医药产业高地。', '生物与新医药技术领域', '/static/defaultImage/1.png', '核心团队由海归生物医药博士、药物研发专家和GMP认证顾问组成。', '计划融资7000万元，出让10%股权，用于研发中心建设和临床试验。', '1001万及以上', '出让股权', 'A轮', 45, 0, 1, 1, '金秀', '13018293503', 'financing_need18@example.com', NULL, NULL, '2025-08-10 14:47:50', '2026-04-29 14:25:41', 0);
