INSERT INTO `technology_achievement` VALUES (1, '海南热带水果保鲜与冷链物流技术', '2021-03-25 09:38:53', '科研', 'https://www.tech110.net/portal.php?mod=view&aid=143562', '针对芒果、荔枝、龙眼等海南特色热带水果，研发的新型生物保鲜剂与智能冷链监控系统，可延长货架期15-20天，减少采后损耗30%以上。该技术已在三亚、陵水等地示范应用。', '食品加工', '/static/defaultImage/1.png', 4, 3, 1, '谢娟', '13277282530', 'technology_achievement1@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (2, '深海网箱养殖智能监测系统', '2021-03-25 14:53:28', '产品', 'https://www.haust.edu.cn/', '基于物联网与水下声呐技术的深远海养殖监测系统，可实现水质参数实时监测、鱼类行为分析、自动投喂控制。已在西沙海域完成中试，适用于金鲳鱼、石斑鱼等海南优势品种。', '海洋工程装备', '/static/defaultImage/1.png', 14, 1, 1, '褚红伟', '15022327528', 'technology_achievement2@example.com', 3, 2, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (3, '橡胶树高产抗病新品种\"海橡7号\"', '2021-03-25 15:01:12', '品种', 'http://www.lvjoe.com', '海南省农科院橡胶研究所培育的橡胶树新品种，具有高产、抗白粉病、耐风害等优良性状。亩产干胶较传统品种提高25%，已在儋州、白沙等植胶区推广种植5万亩。', '农业', '/static/defaultImage/1.png', 17, 1, 1, '张敏辰', '18725950209', 'technology_achievement3@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (4, '海南旅游大数据智能分析平台', '2021-09-29 20:12:19', '产品', NULL, '面向海南自由贸易港建设的旅游大数据分析平台，整合景区客流、酒店入住、交通出行等多源数据，实现游客画像分析、消费趋势预测、景区承载量预警。已接入三亚、海口等主要旅游城市。', '互联网+', '/static/defaultImage/1.png', 20, NULL, 1, '赵洋', '13848927027', 'technology_achievement4@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (5, '海洋波浪能发电装置', '2021-09-29 21:01:34', '产品', NULL, '利用海南丰富海洋波浪能资源研发的浮式波浪能发电装置，单机装机容量100kW，转换效率达35%。适用于南海岛礁供电，已在永兴岛完成示范运行，可有效解决偏远岛礁能源供应问题。', '资源与环境', '/static/defaultImage/1.png', 20, NULL, NULL, '钱洋霞', '13846644625', 'technology_achievement5@example.com', 3, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (6, '热带作物绿色防控集成技术', '2021-09-29 21:03:28', '科研', NULL, '针对海南冬季瓜菜、热带水果等作物，集成生物防治、物理防治、生态调控等技术的绿色防控体系。减少化学农药使用量40%以上，已在乐东、东方等蔬菜主产区大面积推广。', '农业', '/static/defaultImage/1.png', 20, NULL, NULL, '严涛怡', '18873802002', 'technology_achievement6@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (7, '椰壳基高性能活性炭制备工艺', '2021-09-29 21:18:16', '产品', NULL, '以海南丰富的椰壳为原料，采用物理-化学联合活化法制备高性能活性炭。比表面积达1500m²/g以上，碘吸附值>1000mg/g，广泛应用于水处理、空气净化、食品加工等领域。', '新材料', '/static/defaultImage/1.png', 21, NULL, NULL, '孔静', '18728902844', 'technology_achievement7@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (8, '槟榔深加工综合利用技术', '2021-09-29 21:22:28', '科研', NULL, '针对海南槟榔产业开发的深加工技术，包括槟榔碱高效提取、槟榔纤维复合材料制备、槟榔花功能性成分开发等。实现槟榔全产业链高值化利用，产值提升3-5倍。', '食品加工', '/static/defaultImage/1.png', 22, NULL, NULL, '秦国', '15976658645', 'technology_achievement8@example.com', 3, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (9, '南海珊瑚礁生态修复技术', '2022-04-07 15:30:00', '科研', '', '基于珊瑚有性繁殖与无性培育的珊瑚礁生态修复技术体系，包括珊瑚人工育苗、珊瑚移植、礁体构建等关键技术。已在三亚蜈支洲岛、西沙七连屿等海域成功修复珊瑚礁面积5000余平方米。', '资源与环境', '/static/defaultImage/1.png', 4, 3, 1, '卫伟杰', '15002553274', 'technology_achievement9@example.com', 4, 2, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (10, '海南黎锦数字化保护与传承平台', '2022-04-07 15:30:00', '产品', '', '运用高光谱成像、三维建模、区块链存证等技术，对海南黎族传统纺染织绣技艺进行数字化记录与保护。建立黎锦纹样数据库，开发智能设计系统，助力非遗活态传承与文创产品开发。', '互联网+', '/static/defaultImage/1.png', 14, 1, 1, '孔艳伟', '18655292774', 'technology_achievement10@example.com', 4, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (11, '热带兰花组培快繁技术', '2022-04-07 15:30:00', '品种', '', '建立文心兰、石斛兰、蝴蝶兰等热带兰花的无菌组培快繁体系，增殖系数达8-10倍，移栽成活率95%以上。年产优质组培苗100万株，已出口至东南亚及欧美市场。', '农业', '/static/defaultImage/1.png', 14, 1, 1, '何杰', '18265933880', 'technology_achievement11@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (12, '海岛反渗透海水淡化膜材料', '2022-04-07 15:30:00', '产品', '', '针对南海高盐度海水特征研发的高通量反渗透膜材料，脱盐率达99.7%，产水量提高30%，抗生物污染性能优异。适用于西沙、南沙等海岛淡水供应，日处理量可达500吨。', '新材料', '/static/defaultImage/1.png', 14, 1, 1, '柏华', '15587630343', 'technology_achievement12@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (13, '海南沉香人工结香技术', '2022-04-07 15:30:00', '科研', '', '突破白木香树人工结香关键技术，通过微创伤诱导与微生物接种相结合，结香周期从自然状态的数十年缩短至3-5年，沉香品质达到野生沉香水平。已在屯昌、澄迈等地推广种植10万株。', '生物医药', '/static/defaultImage/1.png', 21, 0, 0, '孔超', '18787820177', 'technology_achievement13@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (14, '远洋渔船北斗智能导航系统', '2022-04-07 15:30:00', '产品', '', '集成北斗三号定位、AIS船舶识别、海洋环境预报等功能的远洋渔船智能导航系统。具备船位监控、渔情预报、应急救援、电子渔捞日志等功能，已装备海南籍远洋渔船200余艘。', '先进制造业', '/static/defaultImage/1.png', 21, 0, 0, '章平', '18599537743', 'technology_achievement14@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (15, '海南火山岩矿泉水开发技术', '2022-04-07 15:25:00', '产品', '', '基于海口雷琼火山群地质特征，研发的火山岩深层矿泉水勘探与开发技术。水源经多层火山岩天然过滤，富含偏硅酸、锶等矿物质，达到国家饮用天然矿泉水标准。', '资源与环境', '/static/defaultImage/1.png', 22, 0, 0, '魏磊勇', '13143148125', 'technology_achievement15@example.com', 5, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (16, '热带雨林生态旅游资源评价系统', '2022-09-05 15:38:44', '产品', NULL, '面向海南热带雨林国家公园建设的生态旅游资源评价与规划系统，整合生物多样性、景观美学、游憩价值等多维指标。已在五指山、鹦哥岭等保护区应用，支撑生态旅游可持续发展。', '互联网+', '/static/defaultImage/1.png', NULL, NULL, NULL, '卫超', '15086571000', 'technology_achievement16@example.com', 4, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (17, '文昌鸡良种繁育与标准化养殖技术', '2022-09-05 15:48:12', '品种', NULL, '建立文昌鸡核心群选育、分子标记辅助选择、标准化生态养殖等技术体系。年供种能力达50万只，商品鸡出栏合格率98%以上，肉质风味评分显著优于普通肉鸡。', '农业', '/static/defaultImage/1.png', NULL, NULL, NULL, '水艳', '15654965506', 'technology_achievement17@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (18, '海洋生物医药提取纯化技术', '2022-09-28 18:29:44', '科研', 'http://baidu.com', '从南海海绵、珊瑚、海藻等海洋生物中提取活性物质的分离纯化技术，获得多种抗肿瘤、抗病毒先导化合物。其中海绵来源的HK-1化合物已完成临床前研究，具有开发为新药的潜力。', '生物医药', '/static/defaultImage/1.png', 36, 1, 28, '许梅然', '18201849160', 'technology_achievement18@example.com', 3, 2, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (19, '热带海岛被动式节能建筑技术', '2022-09-28 19:18:32', '产品', 'http://baidu.com', '针对海南高温高湿气候特点，研发的自然通风、遮阳隔热、相变储能等被动式节能建筑技术体系。较传统建筑节能40%以上，室内热舒适度显著提升，适用于热带地区住宅与公共建筑。', '新材料', '/static/defaultImage/1.png', 37, 1, 28, '陈磊燕', '13540671974', 'technology_achievement19@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (20, '海南黄花梨家具精细加工技术', '2022-09-28 19:19:09', '产品', 'http://baidu.com', '针对海南黄花梨珍稀木材开发的数控精细加工与榫卯结构优化技术，木材利用率提高20%，产品精度达0.05mm。结合传统木工技艺与现代智能制造，打造高端红木家具品牌。', '先进制造业', '/static/defaultImage/1.png', 37, 1, 28, '邹建涛', '15529460843', 'technology_achievement20@example.com', 4, 4, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (21, '南繁种业智能育种服务平台', '2022-09-28 21:29:33', '产品', 'http://baidu.com', '依托三亚国家南繁科研育种基地，构建的种业大数据与智能育种服务平台。整合表型组、基因组、环境组数据，实现育种材料智能筛选、杂交组合优化预测，服务全国800余家育种单位。', '互联网+', '/static/defaultImage/1.png', 38, 1, 28, '冯明强', '13583283537', 'technology_achievement21@example.com', 4, 2, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (22, '海南邮轮母港智慧管理系统', '2022-09-28 21:36:05', '产品', 'http://baidu.com', '面向三亚凤凰岛国际邮轮母港开发的智慧管理系统，集成旅客通关、船舶调度、港口安防、旅游服务等功能。支持多船同靠作业，旅客通关时间缩短至15分钟以内。', '互联网+', '/static/defaultImage/1.png', 39, 1, 28, '冯明', '13586348352', 'technology_achievement22@example.com', 5, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_achievement` VALUES (23, '热带海岛光储一体化微电网', '2022-09-28 22:22:08', '产品', 'http://baidu.com', '针对海南离岛村落及旅游景区开发的分布式光伏+储能微电网系统，配置智能能量管理系统，可实现并网/离网无缝切换。单系统供电能力50-200kW，已在分界洲岛、加井岛等景区投运。', '资源与环境', '/static/defaultImage/1.png', 41, 1, 28, '魏勇宇', '13155099053', 'technology_achievement23@example.com', 4, 3, '2025-08-10 13:12:05', '2026-04-29 11:38:51', b'0');
INSERT INTO `technology_need` VALUES (1, '高效提取海南沉香精油的关键技术', '2021-03-25 14:04:27', '现有沉香精油提取效率低、品质不稳定，急需开发超临界CO2萃取与分子蒸馏联合工艺，目标提取率提升至85%以上，精油纯度达95%。欢迎有相关技术储备的单位合作开发。', '生物医药', '生物医药', '/static/defaultImage/1.png', 7, 1, '钱红明', '13810192585', 'technology_need1@example.com', NULL, '16,17', '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (2, '橡胶树白粉病绿色防控技术', '2021-03-25 14:11:38', '海南橡胶主产区白粉病频发，传统化学防治污染重、抗药性强。寻求基于生防菌剂、植物免疫诱抗剂的综合防控技术，要求防效达80%以上，减少化学农药使用50%。', '农业', '农业', '/static/defaultImage/1.png', 8, 1, '孔平敏', '18792771362', 'technology_need2@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (3, '热带海水鱼类工厂化循环水养殖技术', '2021-03-25 14:13:23', '为提升海南海水养殖集约化水平，寻求石斑鱼、金鲳鱼等品种的工厂化循环水养殖系统解决方案，包括生物滤池设计、水质在线监测、病害预警等关键技术。', '农业', '海洋工程装备', '/static/defaultImage/1.png', 9, 1, '吕明辰', '18385678942', 'technology_need3@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (4, '海南特色农产品全程冷链保鲜技术', '2022-08-24 14:29:13', '针对芒果、荔枝、火龙果等海南特色农产品采后损耗率高的问题，寻求从田间预冷、冷藏运输到销售终端的全程冷链保鲜技术体系，目标损耗率控制在10%以内。', '食品加工', '食品加工', '/static/defaultImage/1.png', 6, 1, '蒋红怡', '15102812018', 'technology_need4@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (5, '南海台风灾害精准预警与防护技术', '2022-09-28 18:31:08', '海南地处台风高发区，急需开发基于多源卫星遥感和数值模拟的台风路径、强度、风暴潮精准预报系统，以及适用于热带海岛的建筑物抗风加固技术。', '其他', '资源与环境', '/static/defaultImage/1.png', 36, 28, '冯艳静', '13553729846', 'technology_need5@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (6, '南海深远海油气资源勘探技术', '2022-09-28 22:01:30', '面向南海北部深水盆地的油气资源勘探需求，寻求深水地震勘探、海底钻探、油气藏评价等关键技术，水深范围500-3000米，助力海南清洁能源基地建设。', '资源与环境', '资源与环境', '/static/defaultImage/1.png', 40, 28, '魏秀敏', '13112074720', 'technology_need6@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
INSERT INTO `technology_need` VALUES (7, '海南热带雨林生物多样性监测技术', '2022-09-28 22:22:49', '为海南热带雨林国家公园建设提供技术支撑，寻求基于无人机遥感、红外相机网格、环境DNA等技术的生物多样性长期监测方案，实现旗舰物种动态追踪与生态系统健康评估。', '其他', '资源与环境', '/static/defaultImage/1.png', 42, 28, '杨磊', '15844264011', 'technology_need7@example.com', NULL, NULL, '2025-08-10 13:12:05', '2026-04-29 11:38:51', 0);
