  `examine_date` date NULL DEFAULT NULL COMMENT '核准日期',
  `image_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司图片',
  `examine_image` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核所需资料',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
