-- ----------------------------
-- Table structure for company
-- ----------------------------
DROP TABLE IF EXISTS `company`;
CREATE TABLE `company`  (
  `company_id` bigint NOT NULL AUTO_INCREMENT COMMENT '企业id',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业名称',
  `company_type` tinyint NULL DEFAULT NULL COMMENT '企业类型 [1: 财政核拨经费或核拨补助的事业单位，2: 自收自支事业单位，3: 国有或国有控股企业，4: 中央驻琼单位，5: 民营私营企业，6: 三资企业，7: 其他]',
  `unified_social_credit_code` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '统一社会信用代码',
  `legal_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法定代表人',
  `registered_capital` decimal(20, 2) NULL DEFAULT NULL COMMENT '注册资本（元）',
  `establishment_date` date NULL DEFAULT NULL COMMENT '成立日期',
  `business_term_start` date NULL DEFAULT NULL COMMENT '营业期限起始',
  `business_term_end` date NULL DEFAULT NULL COMMENT '营业期限结束',
  `business_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '经营范围',
  `company_introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '企业简介',
  `industry_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业大类',
  `industry_subcategory` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业细分',
  `company_scale` tinyint NULL DEFAULT NULL COMMENT '企业规模 [1: 微型，2: 小型，3：中型，4: 大型]',
  `employee_count` int NULL DEFAULT NULL COMMENT '员工人数',
  `development_stage` tinyint NULL DEFAULT NULL COMMENT '发展阶段 [1：种子期，2：初创期，3：成长期，4：成熟期，5：Pre-IPO]',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省份',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市',
  `district` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区县',
  `detailed_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `company_website` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司网站',
  `status` tinyint NULL DEFAULT 0 COMMENT '审核状态 [0：未审核，1：正在审核，2：审核通过，3：审核失败]',
  `certification_materials` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证材料',
  `high_tech_enterprise` bit(1) NULL DEFAULT b'0' COMMENT '是否高新技术企业',
  `listed_company` bit(1) NULL DEFAULT b'0' COMMENT '是否上市公司',
  `stock_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '股票代码',
  `contact_id` bigint NULL DEFAULT NULL COMMENT '关联联系人id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '关联用户id',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '逻辑删除',
  PRIMARY KEY (`company_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

