DROP TABLE IF EXISTS `consultation`;
CREATE TABLE `consultation`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户id',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '咨询内容类型（1：申报政策 2：金融政策 3：科技服务 4：人才政策 5：科技园区 6：其他）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '咨询内容',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '回复信息对应的咨询信息的id（咨询信息的parent_id为0）\n',
  `publish_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `is_read` tinyint NOT NULL DEFAULT 0 COMMENT '是否已读（0：未读 1：已读）',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鍜ㄨ?鏍囬?',
  `contact_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鑱旂郴浜哄?鍚',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鑱旂郴浜虹數璇',
  `contact_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鑱旂郴浜洪偖绠',
  `status` tinyint NULL DEFAULT 1 COMMENT '鐘舵? [1:寰呭?鐞? 2:澶勭悊涓? 3:宸插畬鎴? 0:宸插叧闂璢',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '淇?敼鏃堕棿',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '閫昏緫鍒犻櫎鏍囧織',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '咨询' ROW_FORMAT = DYNAMIC;

