  `financing_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '融资方式',
  `financing_phase` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '融资阶段',
  `contact_id` bigint NULL DEFAULT NULL COMMENT '联系人id（目前暂时不用联系人表内人员作为联系人）',
  `business_id` bigint NULL DEFAULT NULL COMMENT '企业id',
  `audit_flag` bigint NULL DEFAULT NULL COMMENT '审核结果(audit result)，（0-正在审核中，1-通过，2-不通过）',
  `success_flag` bigint NULL DEFAULT NULL COMMENT '投资状态(success_flag)（0-成功，1-进行中,2-失败）',
  `contact_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人电话',
  `contact_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人邮箱',
  `contact_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系地址',
  `contact_company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人单位',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '淇?敼鏃堕棿',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '鍒犻櫎鏍囪?',
  PRIMARY KEY (`financing_need_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '融资需求' ROW_FORMAT = DYNAMIC;

