-- ----------------------------
-- Table structure for interview_application
-- ----------------------------
DROP TABLE IF EXISTS `interview_application`;
CREATE TABLE `interview_application`  (
  `application_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `user_id` bigint NOT NULL COMMENT '申请用户ID',
  `talent_need_id` bigint NOT NULL COMMENT '岗位ID',
  `company_id` bigint NOT NULL COMMENT '企业ID',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态：0-未办理，1-已同意，2-已拒绝',
  `apply_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `process_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `process_user_id` bigint NULL DEFAULT NULL COMMENT '处理人ID',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注信息',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NULL DEFAULT 0 COMMENT '删除标记',
  PRIMARY KEY (`application_id`) USING BTREE,
  UNIQUE INDEX `uk_user_talent_need`(`user_id` ASC, `talent_need_id` ASC, `deleted` ASC) USING BTREE COMMENT '同一用户对同一岗位只能申请一次',
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_company_id`(`company_id` ASC) USING BTREE,
  INDEX `idx_talent_need_id`(`talent_need_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '面试申请表' ROW_FORMAT = DYNAMIC;

