DROP TABLE IF EXISTS `talent_need`;
CREATE TABLE `talent_need`  (
  `talent_need_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `business_id` bigint NULL DEFAULT NULL COMMENT '企业id',
  `contact_id` bigint NULL DEFAULT NULL COMMENT '联系人id',
  `position` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '职位工作',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `location` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '位置（省市县）',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `job` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '工作内容',
  `demand` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '职位要求',
  `combined_embedding` json NULL COMMENT '组合向量 ( position + job + demand )',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详情图片',
  `degree` tinyint NULL DEFAULT NULL COMMENT '最低学历 [1：博士研究生，2：硕士研究生，3：本科，4：大专，5：中专，6：高中]',
  `salary_min` decimal(10, 2) NULL DEFAULT NULL COMMENT '最低薪资',
  `salary_max` decimal(10, 2) NULL DEFAULT NULL COMMENT '最高薪资',
  `title1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `title2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `title3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `status` tinyint NULL DEFAULT NULL COMMENT '审核状态 [0：未审核，1：正在审核，2：审核通过，3：审核失败]',
  `gmt_create` datetime NULL DEFAULT NULL,
  `gmt_modified` datetime NULL DEFAULT NULL,
  `deleted` tinyint NULL DEFAULT NULL,
  PRIMARY KEY (`talent_need_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 284 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '人才需求' ROW_FORMAT = DYNAMIC;

