  `age` int NULL DEFAULT NULL COMMENT '年龄',
  `degree` tinyint NULL DEFAULT NULL COMMENT '学历 [1：博士研究生，2：硕士研究生，3：本科，4：大专]',
  `profession` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '专业',
  `school` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学校',
  `job` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '求职意向',
  `skill` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '专业技能',
  `combined_embedding` json NULL COMMENT '组合向量 ( profession + job + skill )',
  `experience` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '个人经历',
  `enter_date` date NULL DEFAULT NULL COMMENT '入学时间',
  `graduate_date` date NULL DEFAULT NULL COMMENT '毕业时间',
  `resume_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上传简历',
  `salary_min` decimal(10, 2) NULL DEFAULT NULL COMMENT '期望最低薪资',
  `salary_max` decimal(10, 2) NULL DEFAULT NULL COMMENT '期望最高薪资',
  `job_nature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作性质',
  `job_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '求职状态',
  `quality` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '性格品质',
  `status` tinyint NULL DEFAULT NULL COMMENT '审核状态 [0：未审核，1：正在审核，2：审核通过，3：审核失败]',
