-- ----------------------------
-- Table structure for tech_ach_evaluation_report
-- ----------------------------
DROP TABLE IF EXISTS `tech_ach_evaluation_report`;
CREATE TABLE `tech_ach_evaluation_report`  (
  `tech_ach_evaluation_report_id` bigint NOT NULL AUTO_INCREMENT COMMENT '技术成果评估报告编号',
  `publish_time` datetime NOT NULL COMMENT '发布时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `technology_achievement_id` bigint NULL DEFAULT NULL COMMENT '技术成果id',
  `material` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评估资料',
  `application_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审核状态 [0：未审核，1：正在审核，2：审核通过，3：审核失败]',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核失败的原因',
  `evaluation_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '评估状态 [0：未评估，1：正在评估，2：评估完成]',
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评估结果',
  `level` tinyint NULL DEFAULT NULL COMMENT '成果水平 [1：国际领先，2：国际先进，3：国内领先，4：国内先进，5：国内一般，6：未评价]',
  `maturity` tinyint NULL DEFAULT NULL COMMENT '成熟度 [1：正在研发，2：已有样品，3：通过小试，4：通过中试，5：可以量产]',
  `user_id` bigint NOT NULL COMMENT '用户id',
  PRIMARY KEY (`tech_ach_evaluation_report_id`) USING BTREE,
  INDEX `FK_tech_ach_evaluation_report`(`technology_achievement_id` ASC) USING BTREE,
  CONSTRAINT `FK_tech_ach_evaluation_report` FOREIGN KEY (`technology_achievement_id`) REFERENCES `technology_achievement` (`technology_achievement_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评估申请' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tech_ach_evaluation_report
-- ----------------------------

-- ----------------------------
-- Table structure for technology_achievement
-- ----------------------------
DROP TABLE IF EXISTS `technology_achievement`;
CREATE TABLE `technology_achievement`  (
  `technology_achievement_id` bigint NOT NULL AUTO_INCREMENT COMMENT '技术成果id',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类',
  `website` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '网址',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `field` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业领域',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详情图片',
  `contact_id` bigint NULL DEFAULT NULL COMMENT '联系人id',
  `publisher_type` tinyint NULL DEFAULT NULL COMMENT '发布者类型 [1：企业，2：学校]',
  `publisher_id` bigint NULL DEFAULT NULL COMMENT '企业或者学校id，根据发布者类型判断',
  `contact_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人电话',
  `contact_email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人邮箱',
  `maturity` tinyint NULL DEFAULT NULL COMMENT '成熟度 [1：正在研发，2：已有样品，3：通过小试，4：通过中试，5：可以量产]',
  `level` tinyint NULL DEFAULT NULL COMMENT '成果水平 [1：国际领先，2：国际先进，3：国内领先，4：国内先进，5：国内一般，6：未评价]',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  PRIMARY KEY (`technology_achievement_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '技术成果' ROW_FORMAT = DYNAMIC;

