-- ----------------------------
-- Table structure for user_behavior
-- ----------------------------
DROP TABLE IF EXISTS `user_behavior`;
CREATE TABLE `user_behavior`  (
  `behavior_id` bigint NOT NULL AUTO_INCREMENT COMMENT '琛屼负ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `target_type` tinyint NOT NULL COMMENT '鐩?爣绫诲瀷 [1:宀椾綅, 2:绠?巻, 3:鏀跨瓥, 4:鏂伴椈]',
  `target_id` bigint NOT NULL COMMENT '鐩?爣ID',
  `action_type` tinyint NOT NULL COMMENT '鎿嶄綔绫诲瀷 [1:鏌ョ湅, 2:鍠滄?, 3:涓嶅枩娆? 4:鏀惰棌, 5:鍒嗕韩]',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `gmt_create` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `gmt_modified` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '淇?敼鏃堕棿',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '閫昏緫鍒犻櫎鏍囧織',
  PRIMARY KEY (`behavior_id`) USING BTREE,
  INDEX `idx_user_target`(`user_id` ASC, `target_type` ASC, `target_id` ASC) USING BTREE,
  INDEX `idx_user_action`(`user_id` ASC, `action_type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '鐢ㄦ埛琛屼负琛' ROW_FORMAT = DYNAMIC;

